1	export type Cell = [number, number];
2	
3	const key = ([x, y]: Cell): string => `${x},${y}`;
4	
5	// The eight cells surrounding any cell (self excluded).
6	const NEIGHBOUR_OFFSETS: Cell[] = [
7	  [-1, -1], [-1, 0], [-1, 1],
8	  [0, -1], [0, 1],
9	  [1, -1], [1, 0], [1, 1],
10	];
11	
12	const survivesToNextGeneration = (isAlive: boolean, liveNeighbours: number): boolean =>
13	  liveNeighbours === 3 || (isAlive && liveNeighbours === 2);
14	
15	export function nextGeneration(cells: Cell[]): Cell[] {
16	  const liveSet = new Set(cells.map(key));
17	
18	  // Count how many live neighbours each candidate cell has, keeping the
19	  // candidate's coordinates alongside its count so no decoding is needed.
20	  const neighbours = new Map<string, { cell: Cell; count: number }>();
21	  for (const [x, y] of cells) {
22	    for (const [dx, dy] of NEIGHBOUR_OFFSETS) {
23	      const cell: Cell = [x + dx, y + dy];
24	      const cellKey = key(cell);
25	      const entry = neighbours.get(cellKey) ?? { cell, count: 0 };
26	      entry.count++;
27	      neighbours.set(cellKey, entry);
28	    }
29	  }
30	
31	  // A dead cell with exactly 3 live neighbours is born (reproduction);
32	  // a live cell with 2 or 3 live neighbours survives. The map key is the
33	  // cell's key string, so membership in liveSet needs no recomputation.
34	  const next: Cell[] = [];
35	  for (const [cellKey, { cell, count }] of neighbours) {
36	    const alive = liveSet.has(cellKey);
37	    if (survivesToNextGeneration(alive, count)) {
38	      next.push(cell);
39	    }
40	  }
41	  return next;
42	}
